import numpy as np

grid = np.array([
    [8, 8, 1, 1, 1, 1, 1, 1, 8],
    [8, 8, 1, 8, 1, 8, 8, 8, 8],
    [8, 8, 8, 8, 1, 8, 8, 8, 8],
