    [8, 8, 8, 8, 8, 8, 8, 8, 8],
    [8, 8, 8, 8, 8, 8, 8, 8, 8]
])

# Extract just the 1s
ones_mask = (grid == 1)

# Check for vertical and horizontal symmetries
def is_vsymmetric(mask, center_col=None):
    if center_col is None:
        center_col = mask.shape[1] // 2
    n, m = mask.shape
    for r in range(n):
        for c in range(m // 2):
            if mask[r, c] != mask[r, m-1-c]:
                return False
    return True

def is_hsymmetric(mask, center_row=None):
    if center_row is None:
        center_row = mask.shape[0] // 2
    n, m = mask.shape
    for r in range(n // 2):
        for c in range(m):
            if mask[r, c] != mask[n-1-r, c]:
                return False
    return False

print("Grid shape:", grid.shape)
print("Is v-symmetric:", is_vsymmetric(ones_mask))
print("Is h-symmetric:", is_hsymmetric(ones_mask))

